def separate_paren_groups(paren_string: str) -> List[str]:
    def extract_groups(paren_string):
        groups = []
        group = ''
        count = 0
        for char in paren_string:
            if char == '(':
                count += 1
                if count == 1:
                    group += char
            elif char == ')':
                count -= 1
                if count == 0:
                    group += char
                    groups.append(group)
                    group = ''
            elif count > 0:
                group += char
        return groups

    def remove_spaces(groups):
        return [group.replace(' ', '') for group in groups]

    def separate_groups(groups):
        return [group for group in groups]

    def is_balanced(group):
        stack = []
        for char in group:
            if char == '(':
                stack.append(char)
            elif char == ')':
                if not stack or stack.pop() != '(':
                    return False
        return not stack

    extracted_groups = extract_groups(paren_string)
    cleaned_groups = remove_spaces(extracted_groups)
    separated_groups = separate_groups(cleaned_groups)
    final_groups = [group for group in separated_groups if is_balanced(group)]

    return final_groups
